INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('259f1704-4150-5bf4-b196-880c5f267649'::uuid, '67d4d420-c4a2-5fe9-b67b-3c92436ade0c'::uuid, 'Bâtiments modulaires standards', 'Structure robuste en acier Montage et démontage rapides Solutions modulaires évolutives Confort thermique et acoustique Adaptés à des usages temporaires ou permanents', 'Site office', NULL, NULL, 7500.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/100a6785c2b7.webp', $j$["https://lechantier.ma/uploads/media/100a6785c2b7.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/bureau-de-chantier/batiments-modulaires-standards", "category_fr": "Site office", "supplier_matching_status": "matched", "technical_specifications_detailed": "• v Caractéristiques techniques standard communes :r Structure portante en acier galvanisé ou profilé en acier — souvent avec poteaux et poutres soudés ou boulonnés.r Panneaux sandwich isolants (murs et toiture) constitués d’acier pré laqué + isolant (polystyrène, laine roche, polyuréthane), pour l’isolation thermique et acoustique.r Revêtement extérieur : tôles métalliques profilées ou panneaux sandwich.r Planchers : souvent un panneau isolant + revêtement final (vinyle, carrelage…), selon usage.r Finitions intérieures : plaques de plâtre ou panneaux revêtus pour bureau, vestiaire, etc.r Ces éléments reprennent les caractéristiques générales du modulaire métallique industriel.v Isolation & conformitéLes modules sont généralement isolés thermiquement et peuvent être adaptés au climat localIls respectent les normes de sécurité et de construction modulaires en vigueur.v Adaptabilité & performanceso Adaptables aux besoins clients : bureaux, bases de vie, abris techniques, modules sanitaires, etc.o Rapidement installables (préfabriqués en usine puis assemblés sur site).o Possibilité d’assemblage côte à côte ou superposé selon projet.", "technical_specifications_original": "• v Caractéristiques techniques standard communes :r Structure portante en acier galvanisé ou profilé en acier — souvent avec poteaux et poutres soudés ou boulonnés.r Panneaux sandwich isolants (murs et toiture) constitués d’acier pré laqué + isolant (polystyrène, laine roche, polyuréthane), pour l’isolation thermique et acoustique.r Revêtement extérieur : tôles métalliques profilées ou panneaux sandwich.r Planchers : souvent un panneau isolant + revêtement final (vinyle, carrelage…), selon usage.r Finitions intérieures : plaques de plâtre ou panneaux revêtus pour bureau, vestiaire, etc.r Ces éléments reprennent les caractéristiques générales du modulaire métallique industriel.v Isolation & conformitéLes modules sont généralement isolés thermiquement et peuvent être adaptés au climat localIls respectent les normes de sécurité et de construction modulaires en vigueur.v Adaptabilité & performanceso Adaptables aux besoins clients : bureaux, bases de vie, abris techniques, modules sanitaires, etc.o Rapidement installables (préfabriqués en usine puis assemblés sur site).o Possibilité d’assemblage côte à côte ou superposé selon projet.", "specs": "• v Caractéristiques techniques standard communes :r Structure portante en acier galvanisé ou profilé en acier — souvent avec poteaux et poutres soudés ou boulonnés.r Panneaux sandwich isolants (murs et toiture) constitués d’acier pré laqué + isolant (polystyrène, laine roche, polyuréthane), pour l’isolation thermique et acoustique.r Revêtement extérieur : tôles métalliques profilées ou panneaux sandwich.r Planchers : souvent un panneau isolant + revêtement final (vinyle, carrelage…), selon usage.r Finitions intérieures : plaques de plâtre ou panneaux revêtus pour bureau, vestiaire, etc.r Ces éléments reprennent les caractéristiques générales du modulaire métallique industriel.v Isolation & conformitéLes modules sont généralement isolés thermiquement et peuvent être adaptés au climat localIls respectent les normes de sécurité et de construction modulaires en vigueur.v Adaptabilité & performanceso Adaptables aux besoins clients : bureaux, bases de vie, abris techniques, modules sanitaires, etc.o Rapidement installables (préfabriqués en usine puis assemblés sur site).o Possibilité d’assemblage côte à côte ou superposé selon projet."}$j$::jsonb, 'https://lechantier.ma/en/produits/bureau-de-chantier/batiments-modulaires-standards') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
