INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('0ebbc20c-1a3c-5df1-97b7-77074e42266a'::uuid, '7b50b45f-ce3d-5de0-af66-9e846943c8a8'::uuid, '1054 Technoflex Colle à Carrelage', 'La colle 1054 TECHOFLEX est une mortaise adhésive cimentaire flexible de haute performance . Conçue pour répondre aux exigences modernes des revêtements .', 'Other', NULL, NULL, 180.0, 'MAD', 'Sac', '1 Sac', 'https://lechantier.ma/uploads/media/fe768ccf28a6.webp', $j$["https://lechantier.ma/uploads/media/fe768ccf28a6.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/carrelage-autres/1054-technoflex-colle-a-carrelage", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• La 1054 TECHNOFLEX est adaptée pour :la pose intérieure et extérieure de revêtements au sol et aux murs : tous types et formats de carreaux céramiques, pierres naturelles, marbre, granite, grès, clinker, etc.les zones soumises à forte contrainte : piscines, bassins, chapes à plancher chauffant, zones à variation thermique rapide (terrasses, balcons, chambres froides), et lieux à trafic intense (centres commerciaux, hôpitaux, écoles).", "technical_specifications_original": "• La 1054 TECHNOFLEX est adaptée pour :la pose intérieure et extérieure de revêtements au sol et aux murs : tous types et formats de carreaux céramiques, pierres naturelles, marbre, granite, grès, clinker, etc.les zones soumises à forte contrainte : piscines, bassins, chapes à plancher chauffant, zones à variation thermique rapide (terrasses, balcons, chambres froides), et lieux à trafic intense (centres commerciaux, hôpitaux, écoles).", "specs": "• La 1054 TECHNOFLEX est adaptée pour :la pose intérieure et extérieure de revêtements au sol et aux murs : tous types et formats de carreaux céramiques, pierres naturelles, marbre, granite, grès, clinker, etc.les zones soumises à forte contrainte : piscines, bassins, chapes à plancher chauffant, zones à variation thermique rapide (terrasses, balcons, chambres froides), et lieux à trafic intense (centres commerciaux, hôpitaux, écoles)."}$j$::jsonb, 'https://lechantier.ma/en/produits/carrelage-autres/1054-technoflex-colle-a-carrelage') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('904f9311-c917-5603-9abf-97e42d735ed7'::uuid, '7b50b45f-ce3d-5de0-af66-9e846943c8a8'::uuid, '1055 GRANITECH CIMENT COLLE BLANC', 'La colle 1055 GRANITECH est une colle cimentaire haute performance conçue pour la pose de carreaux et pierres naturelles sur sols et murs, aussi bien en intérieur qu''en extérieur.', 'Other', NULL, NULL, 100.0, 'MAD', 'Sac', '1 Sac', 'https://lechantier.ma/uploads/media/2790868f00cf.webp', $j$["https://lechantier.ma/uploads/media/2790868f00cf.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/carrelage-autres/1055-granitech-ciment-colle-blanc", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Domaines d’applicationPose de carrelages, grès cérame, pierres naturelles, marbre, granit, clinker — tous formats — sur supports cimentaires, anciens carrelages, enduits, chapes. Convient pour murs et sols, en intérieur comme en extérieur. Adaptée aux surfaces soumises à des contraintes élevées : trafic intense (centres commerciaux, hôpitaux, écoles), pierres lourdes, dimensionnements larges.", "technical_specifications_original": "• Domaines d’applicationPose de carrelages, grès cérame, pierres naturelles, marbre, granit, clinker — tous formats — sur supports cimentaires, anciens carrelages, enduits, chapes. Convient pour murs et sols, en intérieur comme en extérieur. Adaptée aux surfaces soumises à des contraintes élevées : trafic intense (centres commerciaux, hôpitaux, écoles), pierres lourdes, dimensionnements larges.", "specs": "• Domaines d’applicationPose de carrelages, grès cérame, pierres naturelles, marbre, granit, clinker — tous formats — sur supports cimentaires, anciens carrelages, enduits, chapes. Convient pour murs et sols, en intérieur comme en extérieur. Adaptée aux surfaces soumises à des contraintes élevées : trafic intense (centres commerciaux, hôpitaux, écoles), pierres lourdes, dimensionnements larges."}$j$::jsonb, 'https://lechantier.ma/en/produits/carrelage-autres/1055-granitech-ciment-colle-blanc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
