INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('0a70c0a2-0e61-5e6c-80cf-7cec725ce23e'::uuid, '34ca4eb1-299b-5ec1-8011-bd4d994972f8'::uuid, 'Casque de chantier', 'Casque industriel léger et robuste avec ventilation intégrée. Conçu pour un confort optimal et une protection fiable dans tous les environnements de travail.', 'Hard hat', NULL, NULL, 25.0, 'MAD', 'Lot', '35 Lot', 'https://lechantier.ma/uploads/media/ab4ca65e5358.webp', $j$["https://lechantier.ma/uploads/media/ab4ca65e5358.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/casque/casque-de-chantier", "category_fr": "Hard hat", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Matériau coque : HDPE (polyéthylène haute densité)Matériau harnais : LDPETaille : 53 - 64 cmPoids : 330gRéglage : Manuel ou molette à cliquetNorme : EN 397:2012 + A1:2012Certification : SATRA 0321Ventilation : 8 ouvertures pour réduire la chaleurConfort : Bande anti-transpiration absorbante et harnais 6 pointsCompatibilité : Emplacements pour coquilles antibruit et visièresCouleurs disponibles : Jaune, rouge, orange, bleu, vert, blancAccessoires : Visières grillagées, transparentes ou teintées", "technical_specifications_original": "• Matériau coque : HDPE (polyéthylène haute densité)Matériau harnais : LDPETaille : 53 - 64 cmPoids : 330gRéglage : Manuel ou molette à cliquetNorme : EN 397:2012 + A1:2012Certification : SATRA 0321Ventilation : 8 ouvertures pour réduire la chaleurConfort : Bande anti-transpiration absorbante et harnais 6 pointsCompatibilité : Emplacements pour coquilles antibruit et visièresCouleurs disponibles : Jaune, rouge, orange, bleu, vert, blancAccessoires : Visières grillagées, transparentes ou teintées", "specs": "• Matériau coque : HDPE (polyéthylène haute densité)Matériau harnais : LDPETaille : 53 - 64 cmPoids : 330gRéglage : Manuel ou molette à cliquetNorme : EN 397:2012 + A1:2012Certification : SATRA 0321Ventilation : 8 ouvertures pour réduire la chaleurConfort : Bande anti-transpiration absorbante et harnais 6 pointsCompatibilité : Emplacements pour coquilles antibruit et visièresCouleurs disponibles : Jaune, rouge, orange, bleu, vert, blancAccessoires : Visières grillagées, transparentes ou teintées"}$j$::jsonb, 'https://lechantier.ma/en/produits/casque/casque-de-chantier') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
