les peuvent être personnalisées par impression DTF ou sérigraphie avec votre logo ou design. Parfaites pour compléter une tenue professionnelle cohérente tout en renforçant votre image de marque sur le terrain."}$j$::jsonb, 'https://lechantier.ma/en/produits/casque/casquette') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
