INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('c8b6b252-78dc-54f1-941a-2bd573065a58'::uuid, 'ab2f4b77-280a-5513-9f2c-f8a5ff1a1937'::uuid, 'CIMENT 45 C/MAROC', 'e Ciment 45, commercialisé par Ciments du Maroc, est un ciment Portland à haute performance, conforme aux normes nationales et internationales', 'Cement', NULL, NULL, 1600.0, 'MAD', 'm²', '500 m²', 'https://lechantier.ma/uploads/media/80b094ca5aa7.webp', $j$["https://lechantier.ma/uploads/media/80b094ca5aa7.webp"]$j$::jsonb, $j$["Agadir"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/ciment/ciment-45-c-maroc", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Type : Ciment Portland CEM I 42,5 R (résistance rapide)Résistance à la compression : ≥ 42,5 MPa à 28 joursTemps de prise : rapide, permettant une mise en œuvre efficaceFinesse : élevée, assurant une bonne réactivité et durabilitéComposition : clinker Portland, gypse et additifs conformes aux normes en vigueurUtilisation : idéal pour les structures béton armé, les fondations, les ouvrages soumis à des charges importantes, les travaux de génie civil et les applications industrielles.", "technical_specifications_original": "• Type : Ciment Portland CEM I 42,5 R (résistance rapide)Résistance à la compression : ≥ 42,5 MPa à 28 joursTemps de prise : rapide, permettant une mise en œuvre efficaceFinesse : élevée, assurant une bonne réactivité et durabilitéComposition : clinker Portland, gypse et additifs conformes aux normes en vigueurUtilisation : idéal pour les structures béton armé, les fondations, les ouvrages soumis à des charges importantes, les travaux de génie civil et les applications industrielles.", "specs": "• Type : Ciment Portland CEM I 42,5 R (résistance rapide)Résistance à la compression : ≥ 42,5 MPa à 28 joursTemps de prise : rapide, permettant une mise en œuvre efficaceFinesse : élevée, assurant une bonne réactivité et durabilitéComposition : clinker Portland, gypse et additifs conformes aux normes en vigueurUtilisation : idéal pour les structures béton armé, les fondations, les ouvrages soumis à des charges importantes, les travaux de génie civil et les applications industrielles."}$j$::jsonb, 'https://lechantier.ma/en/produits/ciment/ciment-45-c-maroc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
