INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f4e04594-20f1-5bc8-a9d5-38cd50f3f30a'::uuid, '33bac6c1-d297-5214-a08d-68a7403d8596'::uuid, 'CIMENT CPJ 45 CIMAT', 'CIMAT 45 – Ciment Portland Haute Résistance Le ciment CIMAT 45 est un ciment Portland de haute performance, spécialement formulé pour les ouvrages exigeant', 'Cement', NULL, NULL, 82.0, 'MAD', 'Sac', '40 Sac', 'https://lechantier.ma/uploads/media/a889f1fd39b5.webp', $j$["https://lechantier.ma/uploads/media/a889f1fd39b5.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/ciment/ciment-cpj-45-cimat", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• une résistance mécanique élevée et une durabilité exceptionnelle. Idéal pour les travaux de grande envergure, il est recommandé pour les dalles industrielles, les ouvrages d’art, les bétons armés fortement sollicités et les chantiers nécessitant un béton résistant aux charges lourdes.Marque : CIMATType : Ciment Portland 45Utilisation : Ouvrages d’art, structures armées, fondations profondes, chantiers de grande soliditéConditionnement : Sac de 50 kgAvantages : Très haute résistance, durabilité, prise régulière, qualité conforme aux normes internationales", "technical_specifications_original": "• une résistance mécanique élevée et une durabilité exceptionnelle. Idéal pour les travaux de grande envergure, il est recommandé pour les dalles industrielles, les ouvrages d’art, les bétons armés fortement sollicités et les chantiers nécessitant un béton résistant aux charges lourdes.Marque : CIMATType : Ciment Portland 45Utilisation : Ouvrages d’art, structures armées, fondations profondes, chantiers de grande soliditéConditionnement : Sac de 50 kgAvantages : Très haute résistance, durabilité, prise régulière, qualité conforme aux normes internationales", "specs": "• une résistance mécanique élevée et une durabilité exceptionnelle. Idéal pour les travaux de grande envergure, il est recommandé pour les dalles industrielles, les ouvrages d’art, les bétons armés fortement sollicités et les chantiers nécessitant un béton résistant aux charges lourdes.Marque : CIMATType : Ciment Portland 45Utilisation : Ouvrages d’art, structures armées, fondations profondes, chantiers de grande soliditéConditionnement : Sac de 50 kgAvantages : Très haute résistance, durabilité, prise régulière, qualité conforme aux normes internationales"}$j$::jsonb, 'https://lechantier.ma/en/produits/ciment/ciment-cpj-45-cimat') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
