INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('a9e75785-f765-57be-8b8d-7bca9c484422'::uuid, '5eaf47b4-1fba-5a21-b95f-425411572000'::uuid, 'Câbles Incendie C2', 'Câble Incendie C2 – Protection Fiable et Performance Supérieure pour Systèmes Critiques', 'Fire detection', NULL, NULL, 3.0, 'MAD', 'm²', '100 Mètre linéaire', 'https://lechantier.ma/uploads/media/5e98988501be.webp', $j$["https://lechantier.ma/uploads/media/5e98988501be.webp"]$j$::jsonb, $j$["Marrakech"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/detection-incendie/cables-incendie-c2", "category_fr": "Fire detection", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Le Câble Incendie C2 offre une protection supérieure dans les systèmes de détection d’incendie grâce à son isolation en PVC et son blindage complet. Conçu pour des températures de -30°C à +70°C, il assure une performance stable et fiable même en cas d’incendie.", "technical_specifications_original": "• Le Câble Incendie C2 offre une protection supérieure dans les systèmes de détection d’incendie grâce à son isolation en PVC et son blindage complet. Conçu pour des températures de -30°C à +70°C, il assure une performance stable et fiable même en cas d’incendie.", "specs": "• Le Câble Incendie C2 offre une protection supérieure dans les systèmes de détection d’incendie grâce à son isolation en PVC et son blindage complet. Conçu pour des températures de -30°C à +70°C, il assure une performance stable et fiable même en cas d’incendie."}$j$::jsonb, 'https://lechantier.ma/en/produits/detection-incendie/cables-incendie-c2') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('85002313-6d2f-5586-b179-8b4e92249cac'::uuid, '5eaf47b4-1fba-5a21-b95f-425411572000'::uuid, 'Centrales conventionnelles', 'Centrales - Détection incendie conventionelle - Teletek', 'Fire detection', NULL, NULL, 1100.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/eedf1d1ef633.webp', $j$["https://lechantier.ma/uploads/media/eedf1d1ef633.webp"]$j$::jsonb, $j$["Marrakech"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/detection-incendie/centrales-conventionnelles", "category_fr": "Fire detection", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Centrale Incendie conventionnelle 2 zones jusque a 16 zones , certifiée aux normes EN54 . détecteurs automatiques d’incendie peuvent être branchés par zone.Un nombre illimité de déclencheurs peuvent y être connectés. MAG est conçue dans une boîte en ABS, pour une facilité d’installation et de maintenance.Elle est adaptée pour les résidences et les locaux administratifs .", "technical_specifications_original": "• Centrale Incendie conventionnelle 2 zones jusque a 16 zones , certifiée aux normes EN54 . détecteurs automatiques d’incendie peuvent être branchés par zone.Un nombre illimité de déclencheurs peuvent y être connectés. MAG est conçue dans une boîte en ABS, pour une facilité d’installation et de maintenance.Elle est adaptée pour les résidences et les locaux administratifs .", "specs": "• Centrale Incendie conventionnelle 2 zones jusque a 16 zones , certifiée aux normes EN54 . détecteurs automatiques d’incendie peuvent être branchés par zone.Un nombre illimité de déclencheurs peuvent y être connectés. MAG est conçue dans une boîte en ABS, pour une facilité d’installation et de maintenance.Elle est adaptée pour les résidences et les locaux administratifs ."}$j$::jsonb, 'https://lechantier.ma/en/produits/detection-incendie/centrales-conventionnelles') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('577699ba-c55d-5b82-9987-af3f9edf2a4b'::uuid, '5eaf47b4-1fba-5a21-b95f-425411572000'::uuid, 'Déclancheur manuel Conventionnelles', 'SensoMAG MCP50 est un déclencheur manuel pour montage en surface', 'Fire detection', NULL, NULL, 156.0, 'MAD', 'm²', '4 Pièce', 'https://lechantier.ma/uploads/media/99efea8da2a9.webp', $j$["https://lechantier.ma/uploads/media/99efea8da2a9.webp"]$j$::jsonb, $j$["Marrakech"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/detection-incendie/declancheur-manuel-conventionnelles", "category_fr": "Fire detection", "supplier_matching_status": "matched", "technical_specifications_detailed": "• SensoMAG MCP50 est un déclencheur manuel pour montage en surface, conçu pourdes systèmes incendie conventionnels. Il est doté d’un voyant LED pour informerl’utilisateur en cas d’incendie ainsi qu’un élément flexible et réarmable pour assurer unfonctionnement fiable et sûr.Livré avec une clé spécial pour test et réarmement.Certifié EN54-11", "technical_specifications_original": "• SensoMAG MCP50 est un déclencheur manuel pour montage en surface, conçu pourdes systèmes incendie conventionnels. Il est doté d’un voyant LED pour informerl’utilisateur en cas d’incendie ainsi qu’un élément flexible et réarmable pour assurer unfonctionnement fiable et sûr.Livré avec une clé spécial pour test et réarmement.Certifié EN54-11", "specs": "• SensoMAG MCP50 est un déclencheur manuel pour montage en surface, conçu pourdes systèmes incendie conventionnels. Il est doté d’un voyant LED pour informerl’utilisateur en cas d’incendie ainsi qu’un élément flexible et réarmable pour assurer unfonctionnement fiable et sûr.Livré avec une clé spécial pour test et réarmement.Certifié EN54-11"}$j$::jsonb, 'https://lechantier.ma/en/produits/detection-incendie/declancheur-manuel-conventionnelles') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('d13156c2-607a-5328-8a3b-1bfaf897adfb'::uuid, '5eaf47b4-1fba-5a21-b95f-425411572000'::uuid, 'Détection Incendie Conventionnelle', 'Détecteur optique de fumée avec un algorithme de traitement numérique', 'Fire detection', NULL, NULL, 126.0, 'MAD', 'm²', '4 Pièce', 'https://lechantier.ma/uploads/media/7735568bb1a4.webp', $j$["https://lechantier.ma/uploads/media/7735568bb1a4.webp"]$j$::jsonb, $j$["Marrakech"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/detection-incendie/detection-incendie-conventionnelle", "category_fr": "Fire detection", "supplier_matching_status": "matched", "technical_specifications_detailed": "• SensoMAG S30 est un détecteur optique de fumée avec un algorithme de traitement numérique. Il est doté d'une compensation automatique d'empoussiérage ainsi qu'un voyant lumineux visible à 360°. SensoMAG S30 est compatible avec tous les systèmes incendie conventionnels dont la centrale incendie peut atteindre un seuil d'alarme compris entre 10mA et 15mA.", "technical_specifications_original": "• SensoMAG S30 est un détecteur optique de fumée avec un algorithme de traitement numérique. Il est doté d'une compensation automatique d'empoussiérage ainsi qu'un voyant lumineux visible à 360°. SensoMAG S30 est compatible avec tous les systèmes incendie conventionnels dont la centrale incendie peut atteindre un seuil d'alarme compris entre 10mA et 15mA.", "specs": "• SensoMAG S30 est un détecteur optique de fumée avec un algorithme de traitement numérique. Il est doté d'une compensation automatique d'empoussiérage ainsi qu'un voyant lumineux visible à 360°. SensoMAG S30 est compatible avec tous les systèmes incendie conventionnels dont la centrale incendie peut atteindre un seuil d'alarme compris entre 10mA et 15mA."}$j$::jsonb, 'https://lechantier.ma/en/produits/detection-incendie/detection-incendie-conventionnelle') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('e210593c-9520-5311-8c7c-f37b2886ac42'::uuid, '5eaf47b4-1fba-5a21-b95f-425411572000'::uuid, 'Sirène d''alarme incendie conventionnelle', 'Hera RSND est une sirène d''alarme incendie conventionnelle avec une entrée pour la connexion à une centrale d''alarme incendie conventionnelle.', 'Fire detection', NULL, NULL, 250.0, 'MAD', 'm²', '2 Pièce', 'https://lechantier.ma/uploads/media/f345c4e1556b.webp', $j$["https://lechantier.ma/uploads/media/f345c4e1556b.webp"]$j$::jsonb, $j$["Marrakech"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/detection-incendie/sirene-d-alarme-incendie-conventionnelle", "category_fr": "Fire detection", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Hera RSND est une sirène d’alarme incendie conventionnelle avec une entrée pour la connexion à une centrale d’alarme incendie conventionnelle. Hera RSND est conçu pour une utilisation en intérieur uniquement. La sirène est facile à installer et se compose de trois parties : une base plane de montage, un corps de sirène et un couvercle en plastique rouge.", "technical_specifications_original": "• Hera RSND est une sirène d’alarme incendie conventionnelle avec une entrée pour la connexion à une centrale d’alarme incendie conventionnelle. Hera RSND est conçu pour une utilisation en intérieur uniquement. La sirène est facile à installer et se compose de trois parties : une base plane de montage, un corps de sirène et un couvercle en plastique rouge.", "specs": "• Hera RSND est une sirène d’alarme incendie conventionnelle avec une entrée pour la connexion à une centrale d’alarme incendie conventionnelle. Hera RSND est conçu pour une utilisation en intérieur uniquement. La sirène est facile à installer et se compose de trois parties : une base plane de montage, un corps de sirène et un couvercle en plastique rouge."}$j$::jsonb, 'https://lechantier.ma/en/produits/detection-incendie/sirene-d-alarme-incendie-conventionnelle') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
