INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('dd8d1bc6-02ee-5595-bf40-927bd1bb23fe'::uuid, '80a799fe-cb3e-5be3-9e1c-b071de8fbf17'::uuid, 'Disjoncteurs Moteur', 'Découvrez notre gamme de disjoncteurs moteurs de la marque Schneider, offrant une protection fiable et efficace pour une large gamme de puissances, allant de 0,75 kW à 110 kW.', 'Circuit breakers & fuses', NULL, NULL, 400.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/14f0954f4d94.webp', $j$["https://lechantier.ma/uploads/media/14f0954f4d94.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/disjoncteur-fusible/disjoncteurs-moteur", "category_fr": "Matériel électrique", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Ces disjoncteurs assurent une sécurité optimale en protégeant les moteurs contre les surcharges, les courts-circuits et les perturbations électriques, garantissant ainsi une exploitation sûre et fiable de vos équipements. Avec leur conception robuste et leur performance éprouvée, les disjoncteurs moteurs Schneider sont la solution idéale pour répondre à vos besoins en matière de protection électrique dans diverses applications industrielles et commerciales. Choisissez la fiabilité avec Schneider pour une protection optimale de vos moteurs électriques.", "technical_specifications_original": "• Ces disjoncteurs assurent une sécurité optimale en protégeant les moteurs contre les surcharges, les courts-circuits et les perturbations électriques, garantissant ainsi une exploitation sûre et fiable de vos équipements. Avec leur conception robuste et leur performance éprouvée, les disjoncteurs moteurs Schneider sont la solution idéale pour répondre à vos besoins en matière de protection électrique dans diverses applications industrielles et commerciales. Choisissez la fiabilité avec Schneider pour une protection optimale de vos moteurs électriques.", "specs": "• Ces disjoncteurs assurent une sécurité optimale en protégeant les moteurs contre les surcharges, les courts-circuits et les perturbations électriques, garantissant ainsi une exploitation sûre et fiable de vos équipements. Avec leur conception robuste et leur performance éprouvée, les disjoncteurs moteurs Schneider sont la solution idéale pour répondre à vos besoins en matière de protection électrique dans diverses applications industrielles et commerciales. Choisissez la fiabilité avec Schneider pour une protection optimale de vos moteurs électriques."}$j$::jsonb, 'https://lechantier.ma/en/produits/disjoncteur-fusible/disjoncteurs-moteur') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
