INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('eac1fd94-fb9e-5fda-a88f-a4df6398cfde'::uuid, '01ee9428-38a2-5728-9fea-45675b1b219b'::uuid, 'PANEL CARRÉ 60X60 BACKLIT INGELEC', 'Ce panneau LED est le choix idéal si vous recherchez un panneau avec de bonnes caractéristiques et une consommation minimale.', 'Lighting', NULL, NULL, 280.0, 'MAD', 'Pièce', '6 Pièce', 'https://lechantier.ma/uploads/media/ec305f514818.webp', $j$["https://lechantier.ma/uploads/media/ec305f514818.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/eclairage/panel-carre-60x60-backlit-ingelec", "category_fr": "Luminaire", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Il a une utilisation répandue dans les bureaux, les centres commerciaux, les hôpitaux, les entrepôts, les restaurants, les supermarchés, les musées... ainsi que dans les maisons et les résidences.Meilleure efficacité lumineuse : 100lm/WLe panel 60x60 Backlit utilisera des cellules LED avec optique en PMMA pour un meilleur rendu lumineux.Diffuseur en PS sans jaunissement.Le driver LED est sans scintillement (indice < 0.02%)Garantie : 3 ans pour les panels Backlit standards et antiéblouissement.Plus de 30% d’économie d’énergie par rapport aux plafonniers basse luminance à tubes fluorescents.Meilleure optimisation de la lumière : 95% de la lumière est dirigée vers le basLumière uniforme et homogèneDesign moderne pour un montage esthétique et sans contraintes d’encombrementMontage en applique, en plafonnier, encastré, apparent ou suspenduDriver externe pour une meilleure fiabilitéRefroidissement : Les panels sont construits avec un cadre en aluminium et une tôle arrière (bac)", "technical_specifications_original": "• Il a une utilisation répandue dans les bureaux, les centres commerciaux, les hôpi