INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('a7bee30d-62be-5c7f-a43f-d6845736222d'::uuid, '12d5376d-b3bd-5c9b-a933-737179018692'::uuid, 'Projecteur logo', 'Projecteur logo professionnel – GOBO DESIGN Solution d''éclairage et de projection personnalisée pour mettre en valeur votre identité visuelle, votre logo ou vos créations. Idéal pour les showrooms, magasins, hôtels, restaurants, espaces commerciaux et projets architecturaux. Une solution élégante pour une projection lumineuse précise et personnalisée, adaptée aux besoins des professionnels.', 'Lighting', 'Gobo design', NULL, 3000.0, 'MAD', 'm²', NULL, 'https://lechantier.ma/gobo/desing', $j$["https://lechantier.ma/gobo/desing"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/eclairage/projecteur-logo", "category_fr": "Luminaire", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/eclairage/projecteur-logo') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('c40e08f8-6ebd-5855-aa06-b6018fbf4408'::uuid, '433c6235-ef86-54ef-885c-13b43dea1609'::uuid, 'PROJECTEUR SMD100W', 'Éclairez vos espace avec ce projecteur led 100w', 'Lighting', NULL, NULL, 170.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/cfffee51af53.webp', $j$["https://lechantier.ma/uploads/media/cfffee51af53.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/eclairage/projecteur-smd100w", "category_fr": "Luminaire", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Éclairez vos espaces avec ce projecteur LED 100W, idéal pour l’extérieur comme pour l’intérieur. Avec une lumière puissante, une faible consommation d’énergie et une longue durée de vie, il offre un éclairage intense parfait pour chantiers, façades, parkings ou jardins. Étanchéité IP66, corps en aluminium résistant, installation facile.", "technical_specifications_original": "• Éclairez vos espaces avec ce projecteur LED 100W, idéal pour l’extérieur comme pour l’intérieur. Avec une lumière puissante, une faible consommation d’énergie et une longue durée de vie, il offre un éclairage intense parfait pour chantiers, façades, parkings ou jardins. Étanchéité IP66, corps en aluminium résistant, installation facile.", "specs": "• Éclairez vos espaces avec ce projecteur LED 100W, idéal pour l’extérieur comme pour l’intérieur. Avec une lumière puissante, une faible consommation d’énergie et une longue durée de vie, il offre un éclairage intense parfait pour chantiers, façades, parkings ou jardins. Étanchéité IP66, corps en aluminium résistant, installation facile."}$j$::jsonb, 'https://lechantier.ma/en/produits/eclairage/projecteur-smd100w') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('7db83ef4-f48c-5184-b318-5a438926024a'::uuid, '031c23ec-33bd-5687-acbe-64f2bb67b75f'::uuid, 'Rail Apparent Aluminium Magnetique', 'Rail apparent en aluminium, 2M / 3M, support pour modules LED et éclairage magnétique, installation facile et design épuré.', 'Lighting', NULL, NULL, 110.0, 'MAD', 'Mètre', '30 Mètre linéaire', 'https://lechantier.ma/uploads/media/d01add3dd227.webp', $j$["https://lechantier.ma/uploads/media/d01add3dd227.webp", "https://lechantier.ma/uploads/media/4f5da830c67a.webp", "https://lechantier.ma/uploads/media/de4aa5ede637.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/eclairage/rail-apparent-aluminium-magnetique", "category_fr": "Luminaire", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Caractéristiques Techniques :✔ Matériau : Aluminium robuste et léger, garantissant une longue durée de vie✔ Dimensions : 26 mm (largeur) x 51 mm (hauteur) – Compact et discret✔ Longueurs disponibles : 2 mètres / 3 mètres pour s’adapter à diverses configurations✔ Type d’installation : Montage apparent, fixation simple sur surfaces planes✔ Compatibilité : Compatible avec modules LED, éclairage magnétique et luminaires standards✔ Finition aluminium naturelle : Peut être personnalisée selon les besoinsAvantages du Rail Apparent Aluminium✔ Structure résistante – Matériau anticorrosion et facile d’entretien✔ Design moderne et minimaliste – S’intègre parfaitement à tout type d’intérieur✔ Modularité maximale – Permet une grande flexibilité pour des installations personnalisées✔ Facilité d’installation – Montage rapide et sécurisé sur surfaces plates✔ Compatible avec une large gamme de luminaires LED et magnétiquesApplications Idéales :Éclairage résidentiel LED – Parfait pour salons, cuisines et couloirsÉclairage commercial LED – Idéal pour boutiques, showrooms et bureauxÉclairage architectural LED – Convient aux galeries, hôtels et espaces modernesÉclairage public et espaces collectifs – Pour magasins, galeries et expositionsGrâce à son installation simplifiée, sa robustesse et sa compatibilité avec des luminaires variés, le Rail Apparent Aluminium est la solution idéale pour un éclairage performant et flexible.", "technical_specifications_original": "• Caractéristiques Techniques :✔ Matériau : Aluminium robuste et léger, garantissant une longue durée de vie✔ Dimensions : 26 mm (largeur) x 51 mm (hauteur) – Compact et discret✔ Longueurs disponibles : 2 mètres / 3 mètres pour s’adapter à diverses configurations✔ Type d’installation : Montage apparent, fixation simple sur surfaces planes✔ Compatibilité : Compatible avec modules LED, éclairage magnétique et luminaires standards✔ Finition aluminium naturelle : Peut être personnalisée selon les besoinsAvantages du Rail Apparent Aluminium✔ Structure résistante – Matériau anticorrosion et facile d’entretien✔ Design moderne et minimaliste – S’intègre parfaitement à tout type d’intérieur✔ Modularité maximale – Permet une grande flexibilité pour des installations personnalisées✔ Facilité d’installation – Montage rapide et sécurisé sur surfaces plates✔ Compatible avec une large gamme de luminaires LED et magnétiquesApplications Idéales :Éclairage résidentiel LED – Parfait pour salons, cuisines et couloirsÉclairage commercial LED – Idéal pour boutiques, showrooms et bureauxÉclairage architectural LED – Convient aux galeries, hôtels et espaces modernesÉclairage public et espaces collectifs – Pour magasins, galeries et expositionsGrâce à son installation simplifiée, sa robustesse et sa compatibilité avec des luminaires variés, le Rail Apparent Aluminium est la solution idéale pour un éclairage performant et flexible.", "specs": "• Caractéristiques Techniques :✔ Matériau : Aluminium robuste et léger, garantissant une longue durée de vie✔ Dimensions : 26 mm (largeur) x 51 mm (hauteur) – Compact et discret✔ Longueurs disponibles : 2 mètres / 3 mètres pour s’adapter à diverses configurations✔ Type d’installation : Montage apparent, fixation simple sur surfaces planes✔ Compatibilité : Compatible avec modules LED, éclairage magnétique et luminaires standards✔ Finition aluminium naturelle : Peut être personnalisée selon les besoinsAvantages du Rail Apparent Aluminium✔ Structure résistante – Matériau anticorrosion et facile d’entretien✔ Design moderne et minimaliste – S’intègre parfaitement à tout type d’intérieur✔ Modularité maximale – Permet une grande flexibilité pour des installations personnalisées✔ Facilité d’installation – Montage rapide et sécurisé sur surfaces plates✔ Compatible avec une large gamme de luminaires LED et magnétiquesApplications Idéales :Éclairage résidentiel LED – Parfait pour salons, cuisines et couloirsÉclairage commercial LED – Idéal pour boutiques, showrooms et bureauxÉclairage architectural LED – Convient aux galeries, hôtels et espaces modernesÉclairage public et espaces collectifs – Pour magasins, galeries et expositionsGrâce à son installation simplifiée, sa robustesse et sa compatibilité avec des luminaires variés, le Rail Apparent Aluminium est la solution idéale pour un éclairage performant et flexible."}$j$::jsonb, 'https://lechantier.ma/en/produits/eclairage/rail-apparent-aluminium-magnetique') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
